import { TaskRepository } from '../domain/TaskRepository';
import { Task } from '../domain/Task';
import { TaskStatus } from '../domain/TaskStatus';

export class InMemoryTaskRepository implements TaskRepository {
  private tasks: Map<string, Task> = new Map();

  save(task: Task): void {
    this.tasks.set(task.id, task);
  }

  findById(id: string): Task | null {
    return this.tasks.get(id) || null;
  }

  findByProjectId(projectId: string): Task[] {
    return Array.from(this.tasks.values()).filter((t) => t.projectId === projectId);
  }

  findByProjectIdAndStatus(projectId: string, status: TaskStatus): Task[] {
    return Array.from(this.tasks.values()).filter((t) => t.projectId === projectId && t.status === status);
  }

  findByProjectIdAndAssignee(projectId: string, userId: string): Task[] {
    return Array.from(this.tasks.values()).filter(
      (t) => t.projectId === projectId && t.assignedToUserId === userId,
    );
  }
}

